class Solution { public: vector<int> findMinHeightTrees(int n,vector<vector<int>>& edges){if(n==1)return{0};vector<vector<int>> graph(n);vector<int> degree(n);for(auto& edge:edges){graph[edge[0]].push_back(edge[1]);graph[edge[1]].push_back(edge[0]);++degree[edge[0]];++degree[edge[1]];}queue<int> leaves;for(int i=0;i<n;++i)if(degree[i]==1)leaves.push(i);int remaining=n;while(remaining>2){int size=leaves.size();remaining-=size;while(size--){int leaf=leaves.front();leaves.pop();for(int neighbor:graph[leaf])if(--degree[neighbor]==1)leaves.push(neighbor);}}vector<int> answer;while(!leaves.empty()){answer.push_back(leaves.front());leaves.pop();}sort(answer.begin(),answer.end());return answer;} };
